package com.fakenewsdetector.exception;
import jakarta.servlet.http.HttpServletRequest; import java.util.*; import org.springframework.http.*; import org.springframework.http.converter.HttpMessageNotReadableException; import org.springframework.web.bind.MethodArgumentNotValidException; import org.springframework.web.bind.annotation.*;
@RestControllerAdvice public class ApiExceptionHandler { private ResponseEntity<Map<String,Object>> error(HttpStatus s,String c,String m){return ResponseEntity.status(s).body(Map.of("success",false,"error",Map.of("code",c,"message",m)));}@ExceptionHandler(MethodArgumentNotValidException.class)ResponseEntity<?> validation(MethodArgumentNotValidException e){return error(HttpStatus.BAD_REQUEST,"VALIDATION_ERROR",e.getBindingResult().getFieldError().getDefaultMessage());}@ExceptionHandler({HttpMessageNotReadableException.class,IllegalArgumentException.class})ResponseEntity<?> bad(Exception e){return error(HttpStatus.BAD_REQUEST,"VALIDATION_ERROR",e.getMessage());}@ExceptionHandler(SecurityException.class)ResponseEntity<?> unauthorized(SecurityException e){return error(HttpStatus.UNAUTHORIZED,"AUTHENTICATION_FAILED",e.getMessage());}@ExceptionHandler(com.fakenewsdetector.client.MlServiceClient.MlUnavailableException.class)ResponseEntity<?> ml(){return error(HttpStatus.SERVICE_UNAVAILABLE,"ML_SERVICE_UNAVAILABLE","Prediction service is temporarily unavailable.");}@ExceptionHandler(Exception.class)ResponseEntity<?> unknown(Exception e){return error(HttpStatus.INTERNAL_SERVER_ERROR,"INTERNAL_ERROR","Unable to process the request.");}}
